test("akcja zamknięcia pokazuje pending i aktualizuje potwierdzoną bazę",async()=>{const task=deferred<unknown>(),save=vi.fn(()=>task.promise);render(<Harness save={save}/>);await act(async()=>fireEvent.click(screen.getByRole("button")));expect(screen.getByRole("button")).toHaveTextContent("Zamykanie");expect(screen.getByRole("button")).toBeDisabled();expect(screen.getByText("Status: closed")).toBeVisible();expect(save).toHaveBeenCalledWith(42);await act(async()=>task.resolve({id:42,status:"closed",version:1}));await waitFor(()=>expect(screen.getByRole("button")).toHaveTextContent("Zamknij ticket"));expect(screen.getByText("Status: closed")).toBeVisible();expect(screen.getByRole("button")).toBeDisabled();});
